begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select ok(not has_table_privilege('authenticated','public.password_recovery_authorizations','select'),'browser cannot read recovery authority');
select ok(not has_table_privilege('service_role','public.password_recovery_authorizations','insert'),'server writes through validating RPC only');
select ok(not has_function_privilege('authenticated','public.record_password_recovery(text,uuid,text,uuid,text)','execute'),'browser cannot grant recovery');
select ok(not has_function_privilege('anon','public.claim_password_recovery(text,uuid,text,uuid,text)','execute'),'anonymous cannot claim recovery');
insert into auth.users(id,email,email_confirmed_at) values ('22000000-0000-4000-8000-000000000157','Reset@example.invalid',now());
insert into auth.sessions(id,user_id) values ('55000000-0000-4000-8000-000000000157','22000000-0000-4000-8000-000000000157'),('55000000-0000-4000-8000-000000000158','22000000-0000-4000-8000-000000000157');
create function pg_temp.record() returns jsonb language sql as $$ select public.record_password_recovery(repeat('a',64),'22000000-0000-4000-8000-000000000157','RESET@example.invalid','55000000-0000-4000-8000-000000000157','https://reset.example.invalid'); $$;
create function pg_temp.claim(session uuid default '55000000-0000-4000-8000-000000000157',origin text default 'https://reset.example.invalid',email text default 'reset@example.invalid') returns jsonb language sql as $$ select public.claim_password_recovery(repeat('a',64),'22000000-0000-4000-8000-000000000157',email,session,origin); $$;
select is(pg_temp.record()->>'code','recorded','verified session gets separate recovery grant');
select is(pg_temp.claim('55000000-0000-4000-8000-000000000158')->>'code','denied','same user different session cannot borrow grant');
select is(pg_temp.claim(origin=>'https://foreign.invalid')->>'code','denied','wrong origin cannot claim');
select is(pg_temp.claim(email=>'other@example.invalid')->>'code','denied','changed email cannot claim');
select is(pg_temp.claim()->>'code','claimed','verified context claims once');
select is(pg_temp.claim()->>'code','denied','duplicate cannot authorize another password write');
select is((select count(*) from public.memberships where user_id='22000000-0000-4000-8000-000000000157'),0::bigint,'recovery creates no membership');
select is(pg_temp.record()->>'code','recorded','fresh verification replaces consumed grant');
update auth.users set banned_until=now()+interval '1 hour' where id='22000000-0000-4000-8000-000000000157';
select is(pg_temp.record()->>'code','denied','active ban cannot grant recovery');
select is(pg_temp.claim()->>'code','denied','active ban cannot use existing grant');
update auth.users set banned_until=now()-interval '1 hour' where id='22000000-0000-4000-8000-000000000157';
select is(pg_temp.record()->>'code','recorded','elapsed ban permits fresh recovery');
select is(pg_temp.claim()->>'code','claimed','elapsed ban permits authorized reset');
update auth.users set banned_until=null where id='22000000-0000-4000-8000-000000000157';
select pg_temp.record();
update public.password_recovery_authorizations set created_at=now()-interval '31 minutes',expires_at=now()-interval '1 minute';
select is(pg_temp.claim()->>'code','denied','expired authority cannot claim');
select public.cleanup_password_recovery();
select is((select count(*) from public.password_recovery_authorizations where subject='22000000-0000-4000-8000-000000000157'),0::bigint,'idle cleanup erases expired grant');
select * from finish();
rollback;
